"""PROTOTYPE — throwaway. Turns snapshot.json into report_data.json for both prototypes."""

import json
import statistics as st
from collections import defaultdict
from pathlib import Path

import requests
from dotenv import dotenv_values

HERE = Path(__file__).parent
S = json.loads((HERE / "snapshot.json").read_text())
TEAM, OPP, NEXT = "Baylor", "Kansas State", "TCU"
GAME_ID = S["meta"]["game_id"]

KEY = dotenv_values("/Users/kristinarash/DEV/CFB_Analytics_Lab/.env")["CFBD_API_KEY"]
H = {"Authorization": f"Bearer {KEY}"}

# ---------------------------------------------------------------- win probability
wp_path = HERE / "wp.json"
if wp_path.exists():
    wp = json.loads(wp_path.read_text())
else:
    wp = requests.get("https://api.collegefootballdata.com/metrics/wp",
                      headers=H, params={"gameId": GAME_ID}, timeout=60).json()
    wp_path.write_text(json.dumps(wp))

R = {"meta": dict(S["meta"]), "game": S["game"]}

# ------------------------------------------------------------------- win prob line
def game_seconds(period, clock_min, clock_sec):
    return (period - 1) * 900 + (900 - (clock_min * 60 + clock_sec))


R["winprob"] = [
    {"t": round(game_seconds(p["period"], *map(int, [p["clock"]["minutes"], p["clock"]["seconds"]])) / 60, 2)
     if isinstance(p.get("clock"), dict) else None,
     "wp": round((p["homeWinProbability"] if S["game"]["home"] == TEAM
                  else 1 - p["homeWinProbability"]), 4),
     "text": p.get("playText", "")[:110],
     "hs": p.get("homeScore"), "as": p.get("awayScore"), "period": p.get("period")}
    for p in wp if p.get("homeWinProbability") is not None
] if isinstance(wp, list) and wp and "homeWinProbability" in wp[0] else []

# ------------------------------------------------------------------ this game box
adv = S["adv_game"][0]
R["box"] = {"offense": adv["offense"], "defense": adv["defense"]}

ppa_game = next((g for g in S["ppa_games"] if g["gameId"] == GAME_ID), None)
R["ppa_game"] = ppa_game
R["ppa_season"] = S["ppa_team_season"][0] if S["ppa_team_season"] else {}
R["ppa_next_opp_season"] = S["ppa_next_opp"][0] if S["ppa_next_opp"] else {}

# season EPA trajectory by week (offense/defense overall)
R["epa_by_week"] = [
    {"week": g["week"], "opponent": g["opponent"],
     "off": g["offense"]["overall"], "def": g["defense"]["overall"]}
    for g in sorted(S["ppa_games"], key=lambda z: z["week"])
]

# ------------------------------------------------------------- P4 benchmark panel
# direction: +1 = higher is better, -1 = lower is better
DIRECTION = {
    "off_success": 1, "off_explosive": 1, "off_ppa": 1, "off_rush_ppa": 1,
    "off_pass_ppa": 1, "off_line_yards": 1, "off_stuff": -1, "off_havoc": -1,
    "def_success": -1, "def_explosive": -1, "def_ppa": -1, "def_havoc": 1,
    "def_line_yards": -1, "def_stuff": 1,
}
LABEL = {
    "off_success": "Success rate", "off_explosive": "Explosiveness",
    "off_ppa": "EPA / play", "off_rush_ppa": "EPA / rush",
    "off_pass_ppa": "EPA / pass", "off_line_yards": "Line yards",
    "off_stuff": "Stuffed rate", "off_havoc": "Havoc allowed",
    "def_success": "Success rate allowed", "def_explosive": "Explosiveness allowed",
    "def_ppa": "EPA / play allowed", "def_havoc": "Havoc created",
    "def_line_yards": "Line yards allowed", "def_stuff": "Stuff rate",
}


def panel(pctl_map, season_row):
    out = []
    for k, d in DIRECTION.items():
        raw = pctl_map.get(k)
        if raw is None:
            continue
        good = raw if d == 1 else 100 - raw
        out.append({"key": k, "label": LABEL[k], "side": k[:3],
                    "pctl_raw": raw, "pctl": round(good, 1),
                    "median": S["p4"]["median"].get(k)})
    return out


R["p4_n"] = S["p4"]["n_teams"]
R["baylor_panel"] = panel(S["p4"]["baylor_pctl"], S["baylor_season_adv"])
R["next_opp_panel"] = panel(S["p4"]["next_opp_pctl"], S["next_opp_season_adv"])
R["p4_median"] = S["p4"]["median"]
R["baylor_season_adv"] = S["baylor_season_adv"]
R["next_opp_season_adv"] = S["next_opp_season_adv"]

# ------------------------------------------------------------- drives + tempo
drives = S["drives"]
bay_dr = [d for d in drives if d["offense"] == TEAM]
opp_dr = [d for d in drives if d["offense"] != TEAM]


def tempo(ds):
    plays = sum(d["plays"] for d in ds)
    secs = sum(d["elapsed"]["minutes"] * 60 + d["elapsed"]["seconds"] for d in ds)
    return {
        "drives": len(ds), "plays": plays, "yards": sum(d["yards"] for d in ds),
        "sec": secs,
        "plays_per_drive": round(plays / len(ds), 2) if ds else 0,
        "sec_per_play": round(secs / plays, 1) if plays else 0,
        "yards_per_drive": round(sum(d["yards"] for d in ds) / len(ds), 1) if ds else 0,
        "scoring_drives": sum(1 for d in ds if d["scoring"]),
        "three_and_outs": sum(1 for d in ds if d["plays"] <= 3 and not d["scoring"]),
    }


R["tempo"] = {"baylor_off": tempo(bay_dr), "baylor_def": tempo(opp_dr)}
R["drive_log"] = [
    {"num": d["driveNumber"], "off": "BU" if d["offense"] == TEAM else "OPP",
     "plays": d["plays"], "yards": d["yards"], "result": d["driveResult"],
     "start_ytg": d["startYardsToGoal"],
     "elapsed": d["elapsed"]["minutes"] * 60 + d["elapsed"]["seconds"],
     "period": d["startPeriod"]}
    for d in sorted(drives, key=lambda z: z["driveNumber"])
]

# snaps by quarter (both sides), from plays
q_off, q_def = defaultdict(int), defaultdict(int)
for p in S["plays"]:
    (q_off if p["offense"] == TEAM else q_def)[p["period"]] += 1
R["snaps_by_quarter"] = [
    {"q": q, "off": q_off.get(q, 0), "def": q_def.get(q, 0)} for q in sorted(set(q_off) | set(q_def))
]

# down/distance volume for Baylor offense
dd = defaultdict(int)
for p in S["plays"]:
    if p["offense"] == TEAM and p.get("down"):
        dd[p["down"]] += 1
R["off_snaps_by_down"] = [{"down": d, "n": dd[d]} for d in sorted(dd)]

# ----------------------------------------------------------- season tempo context
# Baylor plays/game across the season, for "was this a heavy week?"
R["season_tempo"] = [
    {"week": g["week"], "opponent": g["opponent"],
     "off_plays": g["offense"]["plays"], "def_plays": g["defense"]["plays"],
     "off_drives": g["offense"]["drives"], "def_drives": g["defense"]["drives"]}
    for g in sorted(S["adv_games_baylor"], key=lambda z: z["week"])
]
R["next_opp_tempo"] = [
    {"week": g["week"], "opponent": g["opponent"],
     "off_plays": g["offense"]["plays"], "def_plays": g["defense"]["plays"]}
    for g in sorted(S["next_opp_adv_games"], key=lambda z: z["week"])
]

# ------------------------------------------------------------------------ PFF
BAY_TID = "199" if sum(1 for g in S["pff_grades"] if g["team_id"] == "199") > 0 else None
# identify Baylor's team_id by matching the larger roster to the home team; verify below
tid_counts = defaultdict(int)
for g in S["pff_grades"]:
    tid_counts[g["team_id"]] += 1

# game snaps per player (max across grade types = true snap count)
snaps = {}
for g in S["pff_grades"]:
    k = (g["team_id"], g["name"], g["position"])
    snaps[k] = max(snaps.get(k, 0), g["snaps"] or 0)

by_team = defaultdict(list)
for (tid, name, pos), n in snaps.items():
    by_team[tid].append({"name": name, "position": pos, "snaps": n})

R["pff_team_snap_totals"] = {
    tid: {"players": len(v), "snaps": sum(x["snaps"] for x in v)} for tid, v in by_team.items()
}

# grades for the highest-snap Baylor-side players (pick team with home abbreviation BAYLOR)
R["pff_rosters"] = {tid: sorted(v, key=lambda x: -x["snaps"])[:40] for tid, v in by_team.items()}

# grade table: offense + defense grade per player
grade_map = defaultdict(dict)
for g in S["pff_grades"]:
    grade_map[(g["team_id"], g["name"], g["position"])][g["grade_type"]] = g["grade"]
R["pff_grade_rows"] = [
    {"team_id": tid, "name": name, "position": pos,
     "snaps": snaps[(tid, name, pos)], **{k: round(v, 1) for k, v in gm.items() if v is not None}}
    for (tid, name, pos), gm in grade_map.items()
]

# season snap accumulation by player (Baylor games only, all players in those games)
wk_snaps = defaultdict(dict)
for r in S["pff_season_snaps"]:
    wk_snaps[(r["name"], r["position"])][r["week"]] = r["snaps"] or 0
R["pff_season_snap_series"] = [
    {"name": n, "position": p, "weeks": {str(k): v for k, v in sorted(w.items())},
     "total": sum(w.values())}
    for (n, p), w in wk_snaps.items()
]

out = HERE / "report_data.json"
out.write_text(json.dumps(R, indent=1, default=str))
print("wrote", out, f"{out.stat().st_size/1024:.0f} KB")
print("winprob points:", len(R["winprob"]))
print("tempo:", json.dumps(R["tempo"], indent=1))
print("pff team snap totals:", R["pff_team_snap_totals"])
print("snaps_by_quarter:", R["snaps_by_quarter"])

