(function keyPoints() {
  const rows = D.next_opp_panel
    .map(r => ({ ...r, dist: Math.abs(r.pctl - 50) }))
    .sort((a, b) => b.dist - a.dist).slice(0, 3);
  const phrase = r => {
    const strong = r.pctl >= 50;
    const unit = r.side === "off" ? "offense" : "defense";
    return `TCU's ${unit} sits in the ${Math.round(r.pctl)}${ord(Math.round(r.pctl))} percentile ` +
      `for ${r.label.toLowerCase()} among Power Four teams — ` +
      (strong ? "a genuine strength." : "a genuine weakness.");
  };
  const headline = r => {
    const strong = r.pctl >= 50;
    return `${strong ? "Strength" : "Weakness"}: ${r.label}`;
  };
  document.getElementById("keyPoints").innerHTML = rows.map((r, i) => `
    <div class="key">
      <div class="kflag">Edge ${i + 1} · ${r.side === "off" ? "their offense" : "their defense"}</div>
      <div class="kbig">${headline(r)}</div>
      <div class="kbody">${phrase(r)}</div>
    </div>`).join("");
})();

input.new_string:
(function keyPoints() {
  // One card each: what they do well, what they can't do, and where we attack.
  // Picked from the data, not hand-written — each is the extreme of its slice.
  const off = D.next_opp_panel.filter(r => r.side === "off");
  const def = D.next_opp_panel.filter(r => r.side === "def");
  const best = a => a.reduce((m, r) => (r.pctl > m.pctl ? r : m));
  const worst = a => a.reduce((m, r) => (r.pctl < m.pctl ? r : m));
  const P = v => Math.round(v) + ord(Math.round(v)) + " percentile";
  const cards = [
    { flag: "What they lean on", r: best(off), verb: "respect",
      body: r => `TCU's offense sits in the ${P(r.pctl)} of the Power Four for ` +
        `${r.label.toLowerCase()}. It is the most reliable thing they do — plan for it.` },
    { flag: "What they can't do", r: worst(off), verb: "take away",
      body: r => `Their ${r.label.toLowerCase()} ranks in the ${P(r.pctl)}. ` +
        `Make them do this and the drive stalls.` },
    { flag: "Where we attack", r: worst(def), verb: "attack",
      body: r => `TCU's defense ranks in the ${P(r.pctl)} for ` +
        `${r.label.toLowerCase().replace(" allowed", "")}. This is the softest spot on their side of the ball.` },
  ];
  document.getElementById("keyPoints").innerHTML = cards.map(c => `
    <div class="key">
      <div class="kflag">${c.flag}</div>
      <div class="kbig">${c.r.label.replace(" allowed", "")}</div>
      <div class="kbody">${c.body(c.r)}</div>
    </div>`).join("");
})();

