attachment.snippet:
1	<!--
2	THESIS: Read the team the way you read an athlete — every metric drawn against its
3	Power Four reference range, with only out-of-range values marked. Refuses the
4	sports-analytics card grid: no tiles, no dashboard, no hero metric.
5	OWN-WORLD: Banded chart paper (#f4f5f1 / #e6ece3) on a desk ground, punched left
6	rail, hairline rules, three inks only — black, #2a6ea3 observation blue, #b8433a
7	out-of-range oxide. Archivo Narrow caps for chart labels, Roboto Mono for every
8	number, Source Sans 3 for the few sentences of prose.
9	STORY: A coach picks up a printed sheet Monday, sees two marked values in ninety
10	seconds, and knows what last Saturday says and what TCU demands.
11	FIRST VIEWPORT: A letter sheet. Boxed chart header naming the game, then the
12	full-width win-probability trace with its scoring events listed beneath it as type,
13	then the first banded observation rows.
14	FORM: Monitoring chart; candidate 3 of the grounded list; seed key e7134ed7.
15	FINISH: unreviewed and undocumented is unfinished; this build ends with the finish review, the verdict, and DESIGN.md
16	-->
17	<title>Baylor Game Chart</title>
18	<link rel="preconnect" href="https://fonts.googleapis.com">
19	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
20	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo+Narrow:wght@400;500;600;700&family=Roboto+Mono:wght@400;500;700&family=Source+Sans+3:ital,wght@0,400;0,600;1,400&display=swap">
21	<style>
22	:root{
23	  color-scheme: light;
24	  --desk:#c9ccc3;
25	  --paper:#f4f5f1;
26	  --band:#e6ece3;
27	  --ink:#15181a;
28	  --ink-2:#454e4b;
29	  --ink-3:#6d7773;
30	  --rule:#aab3ac;
31	  --rule-hair:#c6cdc5;
32	  --ref:#ccd6d9;        /* reference range fill */
33	  --obs:#2a6ea3;        /* observed value — ink 2 */
34	  --out:#b8433a;        /* out of range — ink 3 */
35	  --mono:"Roboto Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
36	  --lab:"Archivo Narrow","Arial Narrow",sans-serif;
37	  --prose:"Source Sans 3",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
38	}
39	*{box-sizing:border-box}
40	body{margin:0;background:var(--desk);color:var(--ink);font-family:var(--prose);
41	  font-size:11pt;line-height:1.5;-webkit-font-smoothing:antialiased}
42	
43	/* --------------------------------------------------------------- the sheet */
44	.stack{display:flex;flex-direction:column;align-items:center;gap:26px;padding:26px 12px 60px}
45	.sheet{
46	  position:relative;width:8.5in;min-height:11in;background:var(--paper);
47	  padding:0.5in 0.5in 0.5in 0.86in;
48	  box-shadow:0 6px 20px rgba(20,28,24,.26);
49	}
50	/* punched rail — a material of the paper, drawn not decorated */
51	.sheet::before{
52	  content:"";position:absolute;left:0;top:0;bottom:0;width:0.62in;
53	  border-right:1px solid var(--rule-hair);
54	  background-image:radial-gradient(circle at 0.31in 0.9in, var(--desk) 0 0.085in, transparent 0.087in),
55	                   radial-gradient(circle at 0.31in 50%,   var(--desk) 0 0.085in, transparent 0.087in),
56	                   radial-gradient(circle at 0.31in calc(100% - 0.9in), var(--desk) 0 0.085in, transparent 0.087in);
57	  background-repeat:no-repeat;
58	}
59	.sheetno{position:absolute;right:0.5in;bottom:0.3in;font-family:var(--mono);
60	  font-size:7.5pt;color:var(--ink-3);letter-spacing:.06em}
61	.contfoot{position:absolute;left:0.86in;bottom:0.3in;font-family:var(--lab);
62	  font-size:7.5pt;color:var(--ink-3);letter-spacing:.14em;text-transform:uppercase}
63	
64	/* ------------------------------------------------------------- chart header */
65	.chdr{border:1.5px solid var(--ink);margin-bottom:16px}
66	.chdr .rowa{display:grid;grid-template-columns:1fr 1fr 0.9fr;border-bottom:1px solid var(--ink)}
67	.chdr .rowb{display:grid;grid-template-columns:repeat(4,1fr)}
68	.cell{padding:6px 10px 7px;border-right:1px solid var(--rule-hair)}
