/* ================================================= 6. season trace rows */
(function weeks() {
  const rows = D.epa_by_week.filter(r => r.week <= D.meta.week);
  const vals = rows.flatMap(r => [r.off, r.def]);
  const lo = Math.min(...vals, 0), hi = Math.max(...vals, 0);
  const span = (hi - lo) || 1;
  const W = 220, h = 15;
  const X = v => 4 + ((v - lo) / span) * (W - 8);
  document.getElementById("weekRows").innerHTML = rows.map(r => {
    const better = r.off > r.def;   // outgained the opponent in EPA terms that week
    return `<tr class="${r.week === D.meta.week ? "flagged" : ""}">
      <td>${r.week}</td>
      <td class="lbl">${esc(r.opponent)}</td>
      <td class="r">${signed(r.off)}</td>
      <td class="r">${signed(r.def)}</td>
      <td class="trk" style="width:2.2in"><div class="track">
        <svg viewBox="0 0 ${W} ${h}" preserveAspectRatio="none" role="img"
             aria-label="Week ${r.week} versus ${esc(r.opponent)}: offense ${signed(r.off)}, defense ${signed(r.def)}">
          <line x1="${X(0)}" y1="1" x2="${X(0)}" y2="${h - 1}" stroke="${C("--rule")}" stroke-width="1"/>
          <line x1="${Math.min(X(r.off), X(r.def))}" y1="${h / 2}"
                x2="${Math.max(X(r.off), X(r.def))}" y2="${h / 2}"
                stroke="${better ? C("--obs") : C("--out")}" stroke-width="1.25"/>
          <circle cx="${X(r.off)}" cy="${h / 2}" r="3.6" fill="${C("--obs")}"/>
          <path d="M${X(r.def)} ${h / 2 - 4.2} L${X(r.def) + 3.6} ${h / 2} L${X(r.def)} ${h / 2 + 4.2} L${X(r.def) - 3.6} ${h / 2}Z"
                fill="${C("--out")}"/>
        </svg></div></td>
    </tr>`;
  }).join("");
  document.getElementById("weekLegend").innerHTML =
    `<span>${markObs(10)} Offense EPA per play, higher is better</span>` +
    `<span><svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true">
       <path d="M6 1.6 10 6 6 10.4 2 6Z" fill="${C("--out")}"/></svg>
       Defense EPA per play allowed, lower is better</span>` +
    `<span>Vertical rule is zero · this week's row is shaded</span>`;
})();

