(function obs() {
  const o = D.tempo.baylor_off, d = D.tempo.baylor_def;
  const st = D.season_tempo;
  const avg = k => st.reduce((s, r) => s + r[k], 0) / st.length;
  const mmss = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
  const rows = [
    { l: "Offensive snaps", a: o.plays, b: avg("off_plays"), better: 1, unit: "" },
    { l: "Defensive snaps", a: d.plays, b: avg("def_plays"), better: -1, unit: "" },
    { l: "Offensive drives", a: o.drives, b: avg("off_drives"), better: 0, unit: "" },
    { l: "Plays per drive, offense", a: o.plays_per_drive, b: null, better: 0, dec: 2,
      note: `defense faced ${d.plays_per_drive}` },
    { l: "Seconds per snap, offense", a: o.sec_per_play, b: null, better: 0, dec: 1,
      note: `defense faced ${d.sec_per_play}` },
    { l: "Time of possession", a: mmss(o.sec), b: null, better: 0, raw: true,
      note: `defense on field ${mmss(d.sec)}` },
    { l: "Three-and-outs forced", a: d.three_and_outs, b: null, better: 0,
      note: `our offense had ${o.three_and_outs}` },
  ];
  document.getElementById("obsRows").innerHTML = rows.map(r => {
    if (r.b == null) return `<tr>
      <td class="lbl">${r.l}</td><td class="r">${r.raw ? r.a : r.a.toFixed(r.dec || 0)}</td>
      <td class="r mid">—</td><td class="r mid">—</td>
      <td class="lbl mid" style="font-size:9.5pt">${r.note}</td></tr>`;
    const diff = r.a - r.b;
    const heavy = diff * r.better < 0;
    const reading = Math.abs(diff) < 2 ? "in line with season average"
      : r.better === 0 ? (diff > 0 ? "above season average" : "below season average")
      : heavy ? "heavier than season average" : "lighter than season average";
    return `<tr class="${heavy && Math.abs(diff) >= 8 ? "flagged" : ""}">
      <td class="lbl">${r.l}</td>
      <td class="r ${heavy && Math.abs(diff) >= 8 ? "out" : ""}">${r.a}</td>
      <td class="r mid">${r.b.toFixed(0)}</td>
      <td class="r">${signed(diff, 0)}</td>
      <td class="lbl mid" style="font-size:9.5pt">${reading}</td></tr>`;
  }).join("");
})();

