    `<b>${snaps(p.this_week)}</b>, above his own ${D.meta.baseline_range} range of ${p.band.lo} to ${p.band.hi} ` +
    `(median ${p.band.med}). Season total ${p.total} across ${p.games} games.`)));
  low.slice(0, 1).forEach(p => cards.push(findingCard(markLow(13), `${p.name} · ${p.position}`,
    `<b>${snaps(p.this_week)}</b>, below his own ${D.meta.baseline_range} range of ${p.band.lo} to ${p.band.hi} ` +
    `(median ${p.band.med}). A drop this size is worth confirming against the availability list.`)));
  const host = document.getElementById("findings");
  host.innerHTML = cards.length ? cards.join("")
    : findingCard(markObs(12), "Nothing outside range",
      "Every charted player sat inside his own prior-week range on Saturday.");
})();

input.new_string:
// The header promises every player outside his own range, so this section lists every
// one of them — no slice. Each is written the same way, above or below.
(function findings() {
  const out = players.filter(p => p.flag && p.band)
    .sort((a, b) => {
      const over = x => x.flag === "high" ? x.this_week - x.band.hi : x.band.lo - x.this_week;
      return over(b) - over(a);
    });
  const card = p => {
    const above = p.flag === "high";
    const by = above ? p.this_week - p.band.hi : p.band.lo - p.this_week;
    return findingCard(above ? markOut(13) : markLow(13), `${p.name} · ${p.position}`,
      `<b>${snaps(p.this_week)}</b>, ${above ? "above" : "below"} his own ` +
      `${D.meta.baseline_range} range of ${p.band.lo} to ${p.band.hi} ` +
      `(median ${p.band.med}) — <b>${by} ${by === 1 ? "snap" : "snaps"} ` +
      `${above ? "past the top" : "under the bottom"} of it</b>. ` +
      (above
        ? `Season total ${p.total} across ${p.games} games.`
        : `A drop this size is worth confirming against the availability list.`));
  };
  const host = document.getElementById("findings");
  host.innerHTML = out.length ? out.map(card).join("")
    : findingCard(markObs(12), "Nothing outside range",
      "Every charted player sat inside his own prior-week range on Saturday.");
  document.getElementById("outCount").textContent =
    out.length ? `${out.length} of ${players.length} players` : "none";
})();

