(function season() {
  const rows = D.season_tempo;
  const all = rows.flatMap(r => [r.off_plays, r.def_plays]);
  const lo = Math.min(...all) - 4, hi = Math.max(...all) + 4;
  const HEAVY = 15;
  const maxGap = Math.max(...rows.map(r => r.def_plays - r.off_plays));
  const worst = rows.find(r => r.def_plays - r.off_plays === maxGap);
  document.getElementById("seasonRows").innerHTML = rows.map(r => {
    const gap = r.def_plays - r.off_plays;
    return `<tr class="${gap === maxGap ? "flagged" : ""}">
      <td>${r.week}</td>
      <td class="lbl">${esc(r.opponent)}</td>
      <td class="r">${r.off_plays}</td>
      <td class="r">${r.def_plays}</td>
      <td class="r ${gap === maxGap ? "out" : "mid"}">${signed(gap)}</td>
      <td class="trk" style="width:2.3in"><div class="track">${pairTrack(r.off_plays, r.def_plays, lo, hi, 240, HEAVY)}</div></td>
    </tr>`;
  }).join("");
  document.getElementById("seasonLegend").innerHTML =
    `<span>${markObs(10)} Offensive plays</span>` +
    `<span><svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true">
       <path d="M6 1.6 10 6 6 10.4 2 6Z" fill="${C("--out")}"/></svg> Defensive plays</span>` +
    `<span>The rule turns oxide only when defensive plays run ${HEAVY}+ above offensive plays</span>`;
  // computed, never written into the markup
  document.getElementById("gapClaim").textContent = maxGap > 0
    ? `Week ${worst.week} carries the season's heaviest gap so far, at ${maxGap} snaps.`
    : `No week so far has put the defense on the field more than the offense.`;

