  const dn = `M${vx} ${mid + 5.2} L${vx - 4.3} ${mid - 4.1} L${vx + 4.3} ${mid - 4.1}Z`;
  const mark =
    p.flag === "high" ? `<path d="${up}" fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`
    : p.flag === "low" ? `<path d="${dn}" fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`
