    : `<circle cx="${vx}" cy="${mid}" r="3.7" fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`;
  // the trigger fence, drawn so the threshold is visible rather than asserted
  const fence = [b.trigger_lo, b.trigger_hi]
    .filter(v => v > 0 && v < SNAP_AXIS_MAX)
    .map(v => `<line x1="${X(v)}" y1="${mid - 6.4}" x2="${X(v)}" y2="${mid + 6.4}"
       stroke="${C("--neutral")}" stroke-width="1" stroke-dasharray="2 2"/>`).join("");
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"
