    <line x1="${X(b.hi)}" y1="${mid - 3.4}" x2="${X(b.hi)}" y2="${mid + 3.4}" stroke="${C("--rule")}"/>
    <rect x="${X(b.p25)}" y="${mid - 4.6}" width="${Math.max(1, X(b.p75) - X(b.p25))}" height="9.2"
          fill="${C("--ref")}" stroke="${C("--ink-3")}" stroke-width="1"/>
    <line x1="${X(b.med)}" y1="${mid - 5.6}" x2="${X(b.med)}" y2="${mid + 5.6}"
          stroke="${C("--ink-2")}" stroke-width="1.2"/>
    ${mark}
  </svg>`;
}

